#include "room_lighting.h"
#include "room_lights.inc"
#include "room_environment.inc"
static const char identity[]="opem-room-light-data-sha256:" OPEM_ROOM_LIGHT_DATA_SHA256;
const char *opem_room_lighting_identity(void){return identity;}
int opem_room_lighting_open(opem_room_lighting *s,GLuint program){
 s->mode=glGetUniformLocation(program,"room_mode");s->number=glGetUniformLocation(program,"room_light_count");s->position_inner=glGetUniformLocation(program,"room_position_inner[0]");s->color_outer=glGetUniformLocation(program,"room_color_outer[0]");s->cube_sampler=glGetUniformLocation(program,"room_cube");s->sun_color=glGetUniformLocation(program,"room_sun_color");s->sun_direction=glGetUniformLocation(program,"room_sun_direction");s->shadow_color=glGetUniformLocation(program,"room_shadow_color");
 {unsigned f;glGenTextures(1,&s->cube);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_CUBE_MAP,s->cube);glPixelStorei(GL_UNPACK_ALIGNMENT,1);for(f=0;f<6;f++)glTexImage2D(GL_TEXTURE_CUBE_MAP_POSITIVE_X+f,0,GL_RGBA8,8,8,0,GL_RGBA,GL_UNSIGNED_BYTE,opem_env_cube[f]);glPixelStorei(GL_UNPACK_ALIGNMENT,4);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_CUBE_MAP,GL_TEXTURE_WRAP_R,GL_CLAMP_TO_EDGE);glActiveTexture(GL_TEXTURE2);glGenTextures(1,&s->lut);glBindTexture(GL_TEXTURE_3D,s->lut);glPixelStorei(GL_UNPACK_ALIGNMENT,1);glTexImage3D(GL_TEXTURE_3D,0,GL_SRGB8_ALPHA8,16,16,16,0,GL_RGBA,GL_UNSIGNED_BYTE,opem_env_lut);glPixelStorei(GL_UNPACK_ALIGNMENT,4);glTexParameteri(GL_TEXTURE_3D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_3D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_3D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_3D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_3D,GL_TEXTURE_WRAP_R,GL_CLAMP_TO_EDGE);glActiveTexture(GL_TEXTURE0);s->lut_sampler=glGetUniformLocation(program,"room_lut");}
 return s->lut_sampler>=0&&s->lut&&s->mode>=0&&s->number>=0&&s->position_inner>=0&&s->color_outer>=0&&s->cube_sampler>=0&&s->sun_color>=0&&s->sun_direction>=0&&s->shadow_color>=0&&s->cube;
}
void opem_room_lighting_upload(const opem_room_lighting *s,int mode){
 float positions[36*4],colors[36*4];unsigned i,j;glUniform1i(s->mode,!!mode);glUniform1i(s->number,OPEM_ROOM_LIGHT_COUNT);if(!mode)return;
 glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_CUBE_MAP,s->cube);glActiveTexture(GL_TEXTURE2);glBindTexture(GL_TEXTURE_3D,s->lut);glActiveTexture(GL_TEXTURE0);glUniform1i(s->cube_sampler,1);glUniform1i(s->lut_sampler,2);glUniform3fv(s->sun_color,1,opem_env_sun_color);glUniform3fv(s->sun_direction,1,opem_env_sun_direction);glUniform4fv(s->shadow_color,1,opem_env_shadow_color);
 for(i=0;i<OPEM_ROOM_LIGHT_COUNT;i++){const opem_room_light *l=opem_room_lights+i;for(j=0;j<3;j++){positions[i*4+j]=l->position[j];colors[i*4+j]=l->color[j]*l->multiplier;}positions[i*4+3]=l->start;colors[i*4+3]=l->end;}
 glUniform4fv(s->position_inner,OPEM_ROOM_LIGHT_COUNT,positions);glUniform4fv(s->color_outer,OPEM_ROOM_LIGHT_COUNT,colors);
}
void opem_room_lighting_close(opem_room_lighting *s){if(s->cube)glDeleteTextures(1,&s->cube);if(s->lut)glDeleteTextures(1,&s->lut);s->cube=0;s->lut=0;}
